/* Transparent record arithmetic and writing checks; no admissions probability model. */
const AdvisingCore=(()=>{
 const points=g=>{const s=String(g??'').trim().toUpperCase(),map={A:4,'A-':3.7,'B+':3.3,B:3,'B-':2.7,'C+':2.3,C:2,'C-':1.7,'D+':1.3,D:1,'D-':0.7,F:0,E:0};return Object.hasOwn(map,s)?map[s]:s!==''&&Number.isFinite(+s)&&+s>=0&&+s<=4?+s:null};
 function gpas(courses,excluded=[]){const groups=new Map(),seen=new Set();let omitted=0;for(const c of [...courses,...excluded,...courses.flatMap(c=>(c.creditOrigins||[]).map(o=>({...o,units:o.units||c.units||(c.imported?'Quarter':null),completed:o.completed??true})))]){const grade=points(c.grade),units=c.units||(c.imported?'Quarter':null),credits=Number(grade===0&&c.attemptedCredits!=null?c.attemptedCredits:c.transcriptCredits??c.credits);if(grade===null||!units||!(credits>0)||c.creditType==='transfer'||c.completed!==true&&!['failed','superseded'].includes(c.attemptStatus)&&!['F','E','0','0.0'].includes(String(c.grade).trim().toUpperCase())){omitted++;continue}const id=[c.institution,c.code,c.term||'',c.grade,c.credits,units].join('|');if(seen.has(id))continue;seen.add(id);const k=[c.institution,units].join('|'),g=groups.get(k)||{institution:c.institution,units,credits:0,qualityPoints:0,attempts:0};g.credits+=credits;g.qualityPoints+=grade*credits;g.attempts++;groups.set(k,g)}return{groups:[...groups.values()].map(g=>({...g,gpa:g.qualityPoints/g.credits})),omitted}}
 function targetGrade(g,target,credits){if(!g||!Number.isFinite(+target)||+target<0||+target>4||!Number.isFinite(+credits)||+credits<=0)return null;const needed=(+target*(g.credits+ +credits)-g.qualityPoints)/+credits;return{needed,possible:needed<=4,minimum:Math.max(0,needed),scenarios:Array.from({length:9},(_,i)=>({grade:i/2,gpa:(g.qualityPoints+i/2*+credits)/(g.credits+ +credits)}))}}
 function writing(text,prompt,limit){const draft=String(text||'').trim(),words=draft.split(/\s+/).filter(Boolean),paragraphs=draft.split(/\n\s*\n/).filter(Boolean),sentences=(draft.match(/[^.!?]+(?:[.!?]+|$)/g)||[]).map(s=>s.trim()).filter(Boolean),strengths=[],improve=[],quote=s=>'“'+s.slice(0,240)+'”';if(words.length)strengths.push('Your draft contains '+words.length+' words across '+paragraphs.length+' paragraph(s).');const action=sentences.find(s=>/\b(?:I|we)\s+(?:built|designed|tested|organized|led|created|developed|helped|taught|worked|cared|measured|revised)\b/i.test(s));if(action)strengths.push('A specific action is visible: '+quote(action));const reflection=sentences.find(s=>/\b(?:I learned|I realized|I discovered|taught me|changed my|made me reconsider)\b/i.test(s));if(reflection)strengths.push('Your draft includes a reflection cue: '+quote(reflection)+' Check that it explains what changed for you.');if(paragraphs.length>1)strengths.push('Paragraph breaks give the reader clear stopping points.');else if(words.length>180)improve.push('This is one long paragraph. Consider separating the experience, outcome and reflection.');if(!prompt?.trim())improve.push('Add the exact application prompt so the detailed review can examine its requirements.');if(+limit>0&&words.length>+limit)improve.push('Cut '+(words.length- +limit)+' words to meet your entered maximum of '+limit+'.');const seen=new Set();for(const sentence of sentences){const key=sentence.toLowerCase().replace(/[^a-z0-9]/g,'');if(key.length<25)continue;if(seen.has(key)&&!improve.some(x=>x.startsWith('Repeated sentence:')))improve.push('Repeated sentence: '+quote(sentence)+' Keep it once unless the repetition serves a deliberate purpose.');seen.add(key)}for(const phrase of ['I have always been passionate','Since I was a child','I want to make a difference'])if(draft.toLowerCase().includes(phrase.toLowerCase()))improve.push('Consider making '+quote(phrase)+' more concrete with an experience only you could describe.');if(!action&&words.length)improve.push('Review whether you describe your own contribution. This local pattern check cannot determine whether an example is strong or relevant.');if(!reflection&&words.length)improve.push('Check whether you explain what you learned or changed. Different phrasing may already communicate this; verify before revising.');return{words:words.length,paragraphs:paragraphs.length,strengths,improve,sentences:sentences.length}}

 return{points,gpas,targetGrade,writing};
})();if(typeof module!=='undefined')module.exports=AdvisingCore;
